<script setup>
import { ref, computed, watch, onMounted, onBeforeUnmount } from 'vue'
import { ElTooltip, ElMessage, ElRadioGroup, ElRadioButton } from 'element-plus'
import { IconPlus, IconSettings, IconWorld, IconPalette, IconLink, IconPencil, IconTrash } from '@tabler/icons-vue'
import Sortable from 'sortablejs'
import AppDialog from './AppDialog.vue'
const props = defineProps({ rows:{type:Number,default:1} })
import '../css/bookmarks.css'

import sites from '../state/site-catalog.json'
const siteDescriptions={'map.baidu.com':'浏览地图、搜索地点、查询公交驾车线路，查看实时路况。','autohome.com.cn':'查询汽车报价、车型图片与资讯，了解选车和用车信息。','12306.cn':'中国铁路购票平台，查询车次、余票与出行信息。','hupu.com':'浏览体育赛事资讯，参与运动与日常生活话题讨论。','ctrip.com':'查询和预订酒店、机票、火车票，规划旅行行程。','maps.google.com':'搜索全球地点，查看地图、路线与周边信息。','sports.qq.com':'浏览体育新闻、赛事动态与比赛资讯。','qunar.com':'搜索机票、酒店与旅游产品，比较出行选择。','dongchedi.com':'查看汽车资讯、车型报价、评测与车友交流。','nba.com':'查看 NBA 赛事、球队、球员与比赛资讯。','nba.qq.com':'浏览 NBA 新闻、比赛动态与篮球资讯。'}
const categoryDescriptions={AI:'探索 AI 工具与创作服务',热门:'发现常用网站与热门内容',影音:'浏览视频、音乐与影音内容',效率:'使用在线工具，处理日常工作',科技:'查看技术资源与开发服务',社交:'发现社区话题，交流分享',购物:'浏览商品与购物信息',阅读:'发现内容与阅读资源',新闻:'浏览资讯与专题内容',图片:'使用视觉设计与绘图工具',学习:'获取学习资源与语言工具'}
Object.assign(siteDescriptions,{'eastmoney.com':'浏览财经资讯、市场行情与投资社区。','10jqka.com.cn':'查询股票行情、市场资讯与财经数据。','xueqiu.com':'浏览投资话题、市场资讯与投资者讨论。','finance.sina.com.cn':'查看财经新闻、股票行情与市场动态。','cls.cn':'浏览财经快讯、公司新闻与市场资讯。','stcn.com':'阅读证券市场新闻与上市公司资讯。','cs.com.cn':'阅读证券财经新闻与资本市场报道。','sse.com.cn':'查询上交所公告、市场数据与业务规则。','szse.cn':'查询深交所公告、市场数据与业务规则。','bse.cn':'查询北交所公告、市场数据与业务规则。','hkex.com.hk':'查看香港交易所市场资讯、公告与服务。','pbc.gov.cn':'查阅货币政策、金融统计与官方公告。','csrc.gov.cn':'查阅证券监管政策、公开信息与公告。','tradingview.com':'查看市场图表、行情与交易社区讨论。','investing.com':'查看全球市场行情、财经资讯与经济日历。','finance.yahoo.com':'浏览金融市场行情、公司资讯与财经新闻。'})
Object.assign(siteDescriptions,{"weread.qq.com":"浏览电子书、书单与读书笔记。","read.douban.com":"发现原创小说、文学作品与阅读专题。","qidian.com":"浏览网络小说、作品榜单与连载更新。","jjwxc.net":"发现原创小说与文学连载作品。","fanqienovel.com":"浏览小说作品、分类与作者资讯。","zongheng.com":"发现网络文学作品与小说连载。","ireader.com":"浏览数字阅读服务与图书资源。","dedao.cn":"发现电子书、有声书与知识课程。","lifeweek.com.cn":"阅读文化、生活与社会专题报道。","chinawriter.com.cn":"阅读文学作品、评论与作家资讯。","nlc.cn":"查询馆藏、数字资源与读者服务。","ncpssd.cn":"检索哲学社会科学期刊与学术文献。","gushiwen.cn":"阅读古诗词、文言文与赏析。","ctext.org":"检索和阅读中国古代典籍。","wikisource.org":"浏览公共领域及自由授权的文本作品。","gutenberg.org":"发现和阅读公共领域电子书。","standardebooks.org":"阅读经过排版整理的公共领域电子书。","goodreads.com":"发现图书、书评与读者书单。"})
Object.assign(siteDescriptions,{"store.steampowered.com":"浏览 PC 游戏、玩家评测与商店活动。","store.epicgames.com":"浏览游戏商店、游戏资讯与优惠活动。","gog.com":"发现 PC 游戏、经典作品与商店优惠。","itch.io":"探索独立游戏、创作者作品与游戏素材。","xbox.com":"查看 Xbox 游戏、主机与订阅服务。","playstation.com":"查看 PlayStation 游戏、主机与官方资讯。","nintendo.com":"浏览任天堂游戏、主机与官方资讯。","taptap.cn":"发现手机游戏、玩家评价与社区讨论。","3839.com":"浏览手机游戏资讯、攻略与玩家社区。","gamersky.com":"查看游戏新闻、评测、攻略与专题。","ali213.net":"浏览游戏资讯、攻略与游戏专题。","3dmgame.com":"查看游戏新闻、攻略与玩家讨论。","gcores.com":"阅读游戏文化内容、专题与社区讨论。","a9vg.com":"浏览主机游戏资讯、评测与玩家社区。","ign.com":"查看游戏新闻、评测与攻略内容。","gamespot.com":"浏览游戏新闻、评测与视频内容。","metacritic.com":"查询游戏及影视作品的评分与评论。","steamdb.info":"查询 Steam 游戏数据、价格记录与更新。","howlongtobeat.com":"查看玩家提交的游戏通关时长。","miyoushe.com":"浏览米哈游游戏资讯、攻略与社区讨论。"})
Object.assign(siteDescriptions,{"huya.com":"观看游戏直播、赛事与互动内容。","douyu.com":"观看游戏直播、赛事与主播互动内容。"})
const describeSite=site=>siteDescriptions[site[1]]||((categoryDescriptions[site[2]]||'访问网站，探索更多内容')+' · '+site[0])
const items=ref([]), root=ref(null), opened=ref(false), section=ref('sites'), managing=ref(false), draft=ref({}), saving=ref(false), fetching=ref(false), search=ref(''), kind=ref('全部'), upload=ref(null), failed=ref(new Set())
let sortable
let navigationObserver
const page = ref(0), navigationWidth = ref(0)
const capacity = computed(() => Math.max(1,Math.floor((navigationWidth.value+10)/54)) * Math.max(1,props.rows))
const pages = computed(() => Math.max(1,Math.ceil(items.value.length/capacity.value)))
const visibleItems = computed(() => items.value.slice(page.value*capacity.value,(page.value+1)*capacity.value))
watch([capacity,pages],() => { page.value = Math.min(page.value,pages.value-1) })
onMounted(() => { navigationObserver = new ResizeObserver(() => { navigationWidth.value = root.value?.clientWidth || 0 }); navigationObserver.observe(root.value) })
onBeforeUnmount(() => navigationObserver?.disconnect())
async function api(path='',options){const r=await fetch('/api/bookmarks'+path,options);const data=await r.json();if(!r.ok||data.error)throw Error(data.error||'操作失败');return data}
async function load(){items.value=await api()}
function hasSite(site){return items.value.some(x=>new URL(x.url).hostname===site[1])}
function normalize(value){return new URL(/^https?:\/\//i.test(value)?value:'https://'+value).href}
function open(item){section.value=item?'custom':'sites';draft.value=item?{...item,url:item.url.replace(/^https:\/\//,'')}:{name:'',url:'',icon:'',color:'#5d8b78'};opened.value=true}
async function save(again=false){if(saving.value)return;saving.value=true;try{const note={...draft.value,url:normalize(draft.value.url.trim())};if(!note.name.trim())throw Error('请填写网站名称');await api('/'+(note.id||crypto.randomUUID()),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(note)});failed.value=new Set();await load();ElMessage.success('已保存');if(again)draft.value={name:'',url:'',icon:'',color:'#5d8b78'};else opened.value=false}catch(e){ElMessage.error(e.message)}finally{saving.value=false}}
async function getIcon(){fetching.value=true;try{const url=new URL(normalize(draft.value.url.trim()));const result=await api('/icon',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:url.href})});draft.value.icon=result.icon;if(!draft.value.name)draft.value.name=url.hostname.replace(/^www\./,'');ElMessage.success('图标已保存到本地')}catch(e){ElMessage.error(e.message)}finally{fetching.value=false}}
function uploadIcon(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024)return ElMessage.error('选择 2MB 以内的 PNG、JPG 或 WebP 图片');const reader=new FileReader();reader.onload=()=>draft.value.icon=reader.result;reader.readAsDataURL(file)}
async function remove(item){try{await api('/'+item.id,{method:'DELETE'});await load();ElMessage.success('已删除')}catch(e){ElMessage.error(e.message)}}
async function addSite(site){draft.value={name:site[0],url:site[1],icon:site[3]||'',color:'#5d8b78'};await save(true)}
async function persistOrder(){try{await api('/order',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(items.value.map(x=>x.id))})}catch(e){ElMessage.error(e.message);await load()}}
async function move(index,delta){const next=index+delta;if(next<0||next>=items.value.length)return;const copy=[...items.value];[copy[index],copy[next]]=[copy[next],copy[index]];items.value=copy;await persistOrder()}
onMounted(async()=>{try{await load();sortable=new Sortable(root.value,{animation:matchMedia('(prefers-reduced-motion: reduce)').matches?0:200,easing:'cubic-bezier(.2,.8,.2,1)',draggable:'.bookmark-item',delay:180,delayOnTouchOnly:true,onEnd:async event=>{if(event.oldDraggableIndex===event.newDraggableIndex)return;const copy=[...items.value];const [item]=copy.splice(page.value*capacity.value+event.oldDraggableIndex,1);copy.splice(page.value*capacity.value+event.newDraggableIndex,0,item);const element=event.item;root.value.removeChild(element);root.value.insertBefore(element,root.value.children[event.oldDraggableIndex]||null);items.value=copy;await persistOrder()}})}catch(e){ElMessage.error(e.message)}})
onBeforeUnmount(()=>sortable?.destroy())
</script>
<template>
  <section class="bookmark-bar" aria-label="网址导航">
    <div ref="root" class="bookmark-icons">
      <div v-for="(item,index) in visibleItems" :key="item.id" class="bookmark-item" :data-id="item.id">
        <ElTooltip :content="item.name" :show-after="200"><a :href="item.url" target="_blank" rel="noopener noreferrer" :aria-label="item.name" :style="{'--bookmark-color':item.color}" @contextmenu.prevent="open(item)" @keydown.alt.left.prevent="move(page*capacity+index,-1)" @keydown.alt.right.prevent="move(page*capacity+index,1)"><span class="bookmark-icon-box"><img v-if="item.icon&&!failed.has(item.id)" :src="item.icon" alt="" loading="lazy" referrerpolicy="no-referrer" @error="failed.add(item.id)"/><span v-else class="bookmark-letter">{{item.name.slice(0,1)}}</span></span></a></ElTooltip>
      </div>
    </div>
    <div class="bookmark-controls"><template v-if="pages > 1"><button aria-label="上一页网址" :disabled="page === 0" @click="page--">‹</button><button aria-label="下一页网址" :disabled="page === pages-1" @click="page++">›</button></template><ElTooltip content="添加网址"><button aria-label="添加网址" @click="open()"><IconPlus :size="20"/></button></ElTooltip><ElTooltip content="管理网址"><button aria-label="管理网址" :aria-pressed="managing" @click="managing=true"><IconSettings :size="19"/></button></ElTooltip></div>
  </section>
  <AppDialog v-model="managing" title="管理网址" :width="880">
    <div class="bookmark-manager"><el-empty v-if="!items.length" description="还没有添加网址"/><article v-for="item in items" :key="item.id" class="bookmark-manager-row"><div class="bookmark-manager-icon" :style="{background:item.color}"><img v-if="item.icon&&!failed.has(item.id)" :src="item.icon" alt="" @error="failed.add(item.id)"/><span v-else>{{item.name.slice(0,1)}}</span></div><div class="bookmark-manager-info"><strong :title="item.name">{{item.name}}</strong><small :title="item.url">{{item.url}}</small></div><div class="bookmark-manager-actions"><ElTooltip content="编辑"><el-button circle :aria-label="'编辑 '+item.name" @click="open(item)"><IconPencil :size="16"/></el-button></ElTooltip><ElTooltip content="删除"><el-button circle type="danger" plain :aria-label="'删除 '+item.name" @click="remove(item)"><IconTrash :size="16"/></el-button></ElTooltip></div></article></div>
  </AppDialog>
  <AppDialog v-model="opened" :title="draft.id?'编辑网址':'添加网址'" :width="1120">
    <div class="bookmark-dialog"><nav aria-label="网址添加方式"><button :aria-pressed="section==='sites'" @click="section='sites'"><IconWorld :size="18"/><span>网站收录</span></button><button :aria-pressed="section==='custom'" @click="section='custom'"><IconPalette :size="18"/><span>自定义图标</span></button></nav>
      <div class="bookmark-panel-viewport"><Transition name="bookmark-panel" mode="out-in"><div v-if="section==='sites'" key="sites" class="bookmark-panel"><el-input v-model="search" placeholder="搜索网站" clearable/><ElRadioGroup v-model="kind" class="bookmark-category-tabs" aria-label="网站分类"><ElRadioButton v-for="c in ['全部','AI','热门','应用','新闻','影音','科技','图片','效率','学习','游戏','购物','社交','阅读','出行','金融','其他']" :key="c" :value="c">{{c}}</ElRadioButton></ElRadioGroup><div class="bookmark-catalog"><el-empty v-if="!sites.some(s=>(kind==='全部'||s[2]===kind)&&s.join(' ').toLowerCase().includes(search.toLowerCase()))" description="暂无匹配网站，可通过自定义添加"/><article v-for="site in sites.filter(s=>(kind==='全部'||s[2]===kind)&&s.join(' ').toLowerCase().includes(search.toLowerCase()))" :key="site[1]"><span class="catalog-site-icon"><img v-if="site[3]" :src="site[3]" alt="" loading="lazy"/><IconWorld v-else :size="36"/></span><div class="catalog-site-copy"><strong>{{site[0]}}</strong><small :title="describeSite(site)">{{describeSite(site)}}</small></div><a class="catalog-site-link" :href="'https://'+site[1]" target="_blank" rel="noopener noreferrer" :aria-label="'打开 '+site[0]"><IconLink :size="16"/></a><el-button size="small" :loading="saving" :disabled="hasSite(site)" @click="addSite(site)">{{hasSite(site)?'已添加':'添加'}}</el-button></article></div></div>
      <div v-else key="custom" class="bookmark-panel"><el-form label-position="top" @submit.prevent="save()"><el-form-item label="网址"><el-input v-model="draft.url" placeholder="example.com"><template #prepend>https://</template><template #append><el-button :loading="fetching" @click="getIcon">获取图标</el-button></template></el-input></el-form-item><el-form-item label="名称"><el-input v-model="draft.name" placeholder="网站名称" maxlength="40"/></el-form-item><el-form-item label="图标"><div class="bookmark-icon-editor"><div class="bookmark-preview" :style="{background:draft.color}"><img v-if="draft.icon" :src="draft.icon" alt="图标预览" @error="draft.icon=''"/><span v-else>{{draft.name?.slice(0,1)||'A'}}</span></div><el-button @click="draft.icon=''">文字图标</el-button><el-button @click="upload.click()">上传图标</el-button><input ref="upload" type="file" accept="image/png,image/jpeg,image/webp" hidden @change="uploadIcon"/></div></el-form-item><el-form-item label="图标颜色"><div class="bookmark-colors"><button v-for="color in ['#5d8b78','#4295db','#c4648c','#b58b54','#5269ac','#665a75','#333333']" :key="color" :style="{background:color}" :aria-label="color" :aria-pressed="draft.color===color" @click="draft.color=color" type="button"/></div></el-form-item><div class="bookmark-save"><el-button type="primary" :loading="saving" @click="save()">保存</el-button><el-button :loading="saving" @click="save(true)">保存并继续</el-button></div></el-form></div></Transition></div>
    </div>
  </AppDialog>
</template>
